package com.bank.idgen.gen;

import java.util.logging.Logger;

// Per-shard sequence: increment by totalShards from a distinct offset → non-overlapping.
public class ShardSequence {
    private static final Logger log = Logger.getLogger(ShardSequence.class.getName());
    private final int totalShards;
    private long current;

    public ShardSequence(int totalShards, int thisShard) {
        this.totalShards = totalShards;
        this.current = thisShard - totalShards;   // so first nextval() = thisShard
    }
    public synchronized long nextId() {
        current += totalShards;                   // 1,5,9,... on shard 1 of 4
        log.fine(() -> "shard id=" + current);
        return current;
    }
}
