package com.bank.idgen.gen;

import java.util.logging.Logger;

// 64-bit = 41 bits timestamp | 10 bits worker | 12 bits per-ms sequence.
public class SnowflakeGenerator {
    private static final Logger log = Logger.getLogger(SnowflakeGenerator.class.getName());
    private static final long EPOCH = 1_700_000_000_000L;   // custom epoch
    private final long workerId;        // unique per node (0..1023)
    private long lastMs = -1L;
    private long seq = 0L;

    public SnowflakeGenerator(long workerId) { this.workerId = workerId; }

    public synchronized long nextId() {
        long now = System.currentTimeMillis();
        if (now == lastMs) {
            seq = (seq + 1) & 0xFFF;                 // 12-bit per-ms counter
            if (seq == 0) while ((now = System.currentTimeMillis()) <= lastMs) { /* spin to next ms */ }
        } else {
            seq = 0;
        }
        lastMs = now;
        long id = ((now - EPOCH) << 22) | (workerId << 12) | seq;   // pack the fields
        log.fine(() -> "snowflake id=" + id + " (worker=" + workerId + ")");
        return id;
    }
}
