package com.bank.idgen.gen;

import java.security.SecureRandom;
import java.util.UUID;

// Time-ordered UUID: millisecond timestamp in the high bits + randomness.
public class UuidV7Generator {
    private final SecureRandom rnd = new SecureRandom();

    public UUID nextId() {
        long ms = System.currentTimeMillis();
        long msb = (ms << 16)                 // 48-bit timestamp in the top bits
                 | 0x7000L                     // version 7
                 | (rnd.nextInt(0x0FFF));      // 12 random bits
        long lsb = (0x8000000000000000L)       // variant
                 | (rnd.nextLong() & 0x3FFFFFFFFFFFFFFFL);
        return new UUID(msb, lsb);             // sorts roughly by creation time
    }
}
