package com.bank.idgen;

import com.bank.idgen.gen.*;
import java.util.*;
import java.util.logging.*;

public class IdGenDemo {
    private static final Logger log = Logger.getLogger(IdGenDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();

        log.info("=== Per-shard sequences (4 shards, non-overlapping) ===");
        Set<Long> all = new TreeSet<>();
        for (int shard = 0; shard < 4; shard++) {
            ShardSequence seq = new ShardSequence(4, shard);
            for (int i = 0; i < 3; i++) all.add(seq.nextId());
        }
        log.info("shard ids (all unique, interleaved): " + all);

        log.info("=== Snowflake ids from two workers ===");
        SnowflakeGenerator w7 = new SnowflakeGenerator(7), w8 = new SnowflakeGenerator(8);
        Set<Long> snow = new LinkedHashSet<>();
        for (int i = 0; i < 2; i++) { snow.add(w7.nextId()); snow.add(w8.nextId()); }
        log.info("snowflake ids (time-sortable, unique): " + snow);

        log.info("=== UUIDv7 ids (time-ordered) ===");
        UuidV7Generator u = new UuidV7Generator();
        for (int i = 0; i < 3; i++) { UUID id = u.nextId(); log.info("uuidv7=" + id); }
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

